func TestQueryNodeMetricSupportsThanosPrometheusLabelsAndFallback(t *testing.T) {
	queries := []string{}
	prom := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		query := r.URL.Query().Get("query")
		queries = append(queries, query)
		w.Header().Set("Content-Type", "application/json")
		if strings.Contains(query, "node_cpu_seconds_total") {
			_, _ = w.Write([]byte(`{"status":"success","data":{"resultType":"vector","result":[]}}`))
			return
		}
		_, _ = w.Write([]byte(`{"status":"success","data":{"resultType":"vector","result":[{"metric":{"node":"worker-1"},"value":[1,"1.25"]}]}}`))
	}))
	defer prom.Close()
	values, err := queryNodeMetric(context.Background(), prometheus.NewClient(prom.URL, ""), map[string]string{"worker-1": "worker-1"}, []string{
		`sum by (instance) (rate(node_cpu_seconds_total[5m]))`,
		`sum by (node) (rate(container_cpu_usage_seconds_total[5m]))`,
	})
	if err != nil || values["worker-1"] != 1.25 || len(queries) != 2 {
		t.Fatalf("unexpected fallback result values=%+v queries=%v err=%v", values, queries, err)
	}
}

func TestNodeMetricAliasesIncludeHostnameAndNodeAddresses(t *testing.T) {
	aliases := nodeMetricAliases([]store.K8sInventoryItem{{Name: "worker-1", Labels: map[string]string{"kubernetes.io/hostname": "worker-a"}, StatusObject: map[string]any{
		"addresses": []any{map[string]any{"type": "InternalIP", "address": "10.0.0.11"}},
	}}})
	for _, alias := range []string{"worker-1", "worker-a", "10.0.0.11"} {
		if aliases[alias] != "worker-1" {
			t.Fatalf("alias %q was not resolved: %+v", alias, aliases)
		}
	}
}

func TestNodeMonitoringWindowSupportsInteractiveTrendRanges(t *testing.T) {
	tests := map[string]time.Duration{"10m": 10 * time.Minute, "30m": 30 * time.Minute, "1h": time.Hour, "6h": 6 * time.Hour, "24h": 24 * time.Hour, "7d": 7 * 24 * time.Hour, "30d": 30 * 24 * time.Hour, "90d": 90 * 24 * time.Hour, "180d": 180 * 24 * time.Hour, "365d": 365 * 24 * time.Hour, "395d": 395 * 24 * time.Hour}
	for input, want := range tests {
		name, window, bucket := nodeMonitoringWindow(input)
		if name != input || window != want || bucket <= 0 {
			t.Fatalf("window %s => name=%s window=%s bucket=%s", input, name, window, bucket)
		}
	}
}

func TestMergePodGPUMetricsAggregatesDevices(t *testing.T) {
	metrics := map[string]store.K8sMetricSample{"prod\x00trainer": {Namespace: "prod", ResourceKind: "Pod", ResourceName: "trainer", CPUMillicores: 750, MemoryBytes: 2 << 30}}
	mergePodGPUMetrics(metrics, []store.K8sGPUSample{
		{Namespace: "prod", Pod: "trainer", UtilizationPct: 40, FramebufferUsedBytes: 8 << 30, TemperatureC: 65},
		{Namespace: "prod", Pod: "trainer", UtilizationPct: 80, FramebufferUsedBytes: 12 << 30, TemperatureC: 72},
	}, time.Now())
	metric := metrics["prod\x00trainer"]
	if !metric.GPUObserved || metric.GPUUtilizationPct != 60 || metric.GPUMemoryUsedBytes != 20<<30 || metric.GPUTemperatureC != 72 || metric.CPUMillicores != 750 {
		t.Fatalf("unexpected Pod GPU aggregate: %+v", metric)
	}
}

func TestLatestPodUsageCombinesLatestCPUAndGPUObservation(t *testing.T) {
	usage := latestPodUsage([]store.K8sMetricSample{
		{ClusterID: "c1", Namespace: "prod", ResourceName: "api", CPUMillicores: 250, MemoryBytes: 512 << 20, ObservedAt: "2026-07-13T01:00:00Z"},
		{ClusterID: "c1", Namespace: "prod", ResourceName: "api", GPUObserved: true, GPUUtilizationPct: 45, GPUMemoryUsedBytes: 4 << 30, ObservedAt: "2026-07-13T00:59:00Z"},
	})[podUsageKey("c1", "prod", "api")]
	if !usage.Available || usage.CPUMillicores != 250 || !usage.GPUObserved || usage.GPUUtilizationPct != 45 {
		t.Fatalf("unexpected latest Pod usage: %+v", usage)
	}
}

func TestK8sNodeAndGPUOperationsEndpoints(t *testing.T) {
	db := openTestStore(t)
	defer db.Close()
	ctx := context.Background()
	if err := db.UpsertK8sCluster(ctx, store.K8sCluster{ID: "c1", Name: "prod", Status: "ready"}); err != nil {
		t.Fatal(err)
	}
	if err := db.UpsertK8sInventory(ctx, store.K8sInventoryItem{ID: "n1", ClusterID: "c1", Kind: "Node", Name: "gpu-1", Status: "Ready", Labels: map[string]string{"nvidia.com/gpu.product": "H100"}, StatusObject: map[string]any{"allocatable": map[string]any{"cpu": "4", "memory": "8Gi", "nvidia.com/gpu": "1"}, "conditions": []any{map[string]any{"type": "Ready", "status": "True"}}}}); err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Format(time.RFC3339Nano)
	if err := db.InsertK8sMetricSample(ctx, store.K8sMetricSample{ID: "m1", ClusterID: "c1", ResourceKind: "Node", ResourceName: "gpu-1", CPUMillicores: 2000, MemoryBytes: 4 << 30, ObservedAt: now}); err != nil {
		t.Fatal(err)
	}
	if err := db.InsertK8sGPUSample(ctx, store.K8sGPUSample{ID: "g1", ClusterID: "c1", NodeName: "gpu-1", GPUUUID: "GPU-1", UtilizationPct: 50, FramebufferUsedBytes: 20 << 30, FramebufferFreeBytes: 60 << 30, TemperatureC: 60, ObservedAt: now}); err != nil {
		t.Fatal(err)
	}
	logger := store.NewAsyncLogger(db, 16, filepath.Join(t.TempDir(), "fallback.ndjson"))
	logger.Start()
	defer logger.Stop(context.Background())
	server, err := NewServer(testConfig("http://upstream.invalid", "secret"), db, logger, nil)
	if err != nil {
		t.Fatal(err)
	}
	proxy := httptest.NewServer(server.Routes())
	defer proxy.Close()

	resp, err := http.Get(proxy.URL + "/admin/k8s/nodes/monitoring?cluster_id=c1&window=1h")
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var nodes struct {
		Report analyzer.NodeMonitoringReport `json:"report"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&nodes); err != nil {
		t.Fatal(err)
	}
	if resp.StatusCode != http.StatusOK || len(nodes.Report.Nodes) != 1 || nodes.Report.Nodes[0].CPU.Percent != 50 {
		t.Fatalf("unexpected node monitoring response: status=%d report=%+v", resp.StatusCode, nodes.Report)
	}

	gpuResp, err := http.Get(proxy.URL + "/admin/k8s/gpu/operations?cluster_id=c1&window=1h")
	if err != nil {
		t.Fatal(err)
	}
	defer gpuResp.Body.Close()
	var gpu struct {
		Report analyzer.GPUOperationsReport `json:"report"`
	}
	if err := json.NewDecoder(gpuResp.Body).Decode(&gpu); err != nil {
		t.Fatal(err)
	}
	if gpuResp.StatusCode != http.StatusOK || gpu.Report.Summary.Devices != 1 || len(gpu.Report.Nodes) != 1 {
		t.Fatalf("unexpected GPU operations response: status=%d report=%+v", gpuResp.StatusCode, gpu.Report)
	}
}

